//! The Harmonic EQ's shapes (generated by tools/gen-harmlib.py): DS Thorn's
//! Harmonic Filter presets, each a curve of 8192 magnitudes over harmonic
//! number, which Thorn reads at harmonic h * k (its sweep moves k). Stored as
//! u16; their powers are summed from the start once, when the plugin loads,
//! so the mean power over any stretch of a curve is two lookups.

use std::sync::OnceLock;

include!("../../../../abdication/plugin/src/harmlib_index.rs");

static DATA: &[u8] = include_bytes!("../../../../abdication/plugin/src/harmlib.bin");

/// Each shape's power (magnitude²) summed from the start: entry i is the sum
/// of entries before i (SIZE + 1 of them).
fn sums() -> &'static [Box<[f64]>] {
    static SUMS: OnceLock<Vec<Box<[f64]>>> = OnceLock::new();
    SUMS.get_or_init(|| {
        (0..NAMES.len())
            .map(|s| {
                let bytes = &DATA[s * SIZE * 2..(s + 1) * SIZE * 2];
                let mut sum = Vec::with_capacity(SIZE + 1);
                let mut total = 0.0f64;
                sum.push(0.0);
                for b in bytes.chunks_exact(2) {
                    let m = u16::from_le_bytes([b[0], b[1]]) as f64 / 65535.0;
                    total += m * m;
                    sum.push(total);
                }
                sum.into_boxed_slice()
            })
            .collect()
    })
}

/// Make the sums now (the plugin does, so the audio thread never does).
pub fn prepare() {
    sums();
}

/// Shape `shape`'s (0-based) summed power up to (fractional) entry `x`.
fn summed(sum: &[f64], x: f64) -> f64 {
    let x = x.clamp(0.0, SIZE as f64);
    let i = (x as usize).min(SIZE - 1);
    sum[i] + (x - i as f64) * (sum[i + 1] - sum[i])
}

/// The mean power of shape `shape` (0-based) over entries [a, b) (fractional;
/// silent past the end, as Thorn's partials past its table are).
pub fn mean_power(shape: usize, a: f32, b: f32) -> f32 {
    let sum = &sums()[shape];
    let (a, b) = (a as f64, (b as f64).max(a as f64 + 1e-6));
    ((summed(sum, b) - summed(sum, a)) / (b - a)) as f32
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn shapes_are_present() {
        assert_eq!(NAMES.len(), 81);
        assert_eq!(DATA.len(), NAMES.len() * SIZE * 2);
        assert_eq!(NAMES[0], "Amp 01");
        // EQ Lows 02 passes its low entries and silences its top.
        let lows = NAMES.iter().position(|n| *n == "EQ Lows 02").unwrap();
        assert!(mean_power(lows, 16.0, 32.0) > 0.5);
        assert!(mean_power(lows, 7000.0, 8000.0) < 1e-6);
        assert_eq!(mean_power(lows, 9000.0, 9100.0), 0.0);
    }
}
